sys_script_include.script:
var GetEventDetails = Class.create();
GetEventDetails.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getEventDetails: function() {
        var eventId = this.getParameter('sysparm_event_id'); // Passed from client script
        var gr = new GlideRecord('x_1790229_event_ma_event_record'); 
        gr.addQuery('number', eventId);
        gr.query();

        if (gr.next()) {
            var result = {
                name: gr.getValue('u_event_name'),
                date: gr.getDisplayValue('u_event_date'),
                location: gr.getValue('u_location'),
                status: gr.getValue('u_status'),
                contact: gr.getValue('u_contact_person'),
                email: gr.getValue('u_email')
            };
            return JSON.stringify(result);
        }
        return JSON.stringify({
            error: 'Event not found'
        });
    },
    IsVipEvent: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790229_event_ma_event_record');
        gr.addQuery('number', eventId);
        gr.query();

        if (gr.next()) {
           return  gr.getValue('u_vip') === '1' ? 'true' : 'false';
        }

        return 'false';
    },

    type: 'GetEventDetails'
});
